//! `DefinitionLinter` against outcomes captured from the pinned Ruby oracle
//! (ukiryu/ukiryu ab6df353, Ruby 4.0.1). The fixture is generated by the
//! K21-LINT capture script; see its `provenance` field.
//!
//! Every captured case runs through `lint` (YAML loaded as `lint_file`
//! loads it), `lint_string` and `lint_file`; each Ruby result is compared
//! on its full `to_h`, `to_s`, `has_issues?` and `has_errors?`, and each
//! Ruby exception on its class and message.
//!
//! Declared differences (asserted, not skipped):
//! - YAML syntax errors: the text after `Invalid YAML: ` is the YAML
//!   engine's message, not libyaml's, so only the prefix, the class and the
//!   result shape are compared.
//! - `<<` merge keys are not reproduced by the YAML loader and report
//!   `LintError::Unsupported`.
use serde_json::Value;
use std::path::PathBuf;
use ukiryu::definition::linter::{
    rules, safe_load_definition, DefinitionLinter, LintError, LintResult, Rule, RuleFilter,
};
use ukiryu::definition::{LintIssue, Severity};

const FIXTURE: &str = include_str!("../src/definition/linter/fixtures/oracle.json");

/// Cases whose YAML the Ruby loader rejects with `Psych::SyntaxError`.
const SYNTAX_CASES: &[&str] = &["spec_invalid_yaml_indent", "spec_invalid_yaml_colon"];

/// Cases this port reports as unsupported (YAML `<<` merge keys).
const UNSUPPORTED_CASES: &[&str] = &["yaml_merge_key_alias", "yaml_merge_key_inline"];

fn fixture() -> Value {
    serde_json::from_str(FIXTURE).expect("fixture parses")
}

fn rule_filter(v: &Value) -> Option<RuleFilter> {
    if v.is_null() {
        return None;
    }
    let list = |key: &str| {
        v.get(key).and_then(Value::as_array).map(|a| {
            a.iter()
                .map(|s| s.as_str().expect("rule id").to_owned())
                .collect::<Vec<_>>()
        })
    };
    Some(RuleFilter {
        enabled: list("enabled"),
        disabled: list("disabled"),
    })
}

fn to_value<T: serde::Serialize>(t: &T) -> Value {
    serde_json::from_str(&serde_json::to_string(t).unwrap()).unwrap()
}

fn tmp_dir(tag: &str) -> PathBuf {
    let dir = std::env::temp_dir().join(format!(
        "ukiryu-linter-{tag}-{}-{:?}",
        std::process::id(),
        std::thread::current().id()
    ));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    dir
}

/// Apply `sub` to every string in a JSON value (not to the JSON text, so
/// Windows path separators need no escaping).
fn subst_value(v: &Value, sub: &dyn Fn(&str) -> String) -> Value {
    match v {
        Value::String(s) => Value::String(sub(s)),
        Value::Array(a) => Value::Array(a.iter().map(|x| subst_value(x, sub)).collect()),
        Value::Object(o) => Value::Object(
            o.iter()
                .map(|(k, x)| (k.clone(), subst_value(x, sub)))
                .collect(),
        ),
        other => other.clone(),
    }
}

/// Compare one Rust outcome with one captured Ruby outcome.
fn check(
    ctx: &str,
    want: &Value,
    got: &Result<LintResult, LintError>,
    path: Option<&str>,
    syntax: bool,
) {
    let sub = |s: &str| match path {
        Some(p) => s.replace("{path}", p),
        None => s.to_owned(),
    };
    match (want["kind"].as_str().unwrap(), got) {
        ("result", Ok(res)) => {
            assert_eq!(
                res.has_issues(),
                want["has_issues"].as_bool().unwrap(),
                "{ctx}: has_issues"
            );
            assert_eq!(
                res.has_errors(),
                want["has_errors"].as_bool().unwrap(),
                "{ctx}: has_errors"
            );
            let want_h = subst_value(&want["to_h"], &sub);
            let got_h = to_value(&res.to_h());
            if syntax {
                assert_eq!(res.count(), 1, "{ctx}: one issue");
                let msg = &res.issues[0].message;
                assert!(msg.starts_with("Invalid YAML: "), "{ctx}: {msg}");
                assert!(
                    want_h["issues"][0]["message"]
                        .as_str()
                        .unwrap()
                        .starts_with("Invalid YAML: "),
                    "{ctx}: oracle message"
                );
                let mut g = got_h.clone();
                let mut w = want_h.clone();
                g["issues"][0]["message"] = Value::Null;
                w["issues"][0]["message"] = Value::Null;
                assert_eq!(g, w, "{ctx}: to_h apart from the engine message");
            } else {
                assert_eq!(got_h, want_h, "{ctx}: to_h");
                assert_eq!(
                    res.to_string(),
                    sub(want["to_s"].as_str().unwrap()),
                    "{ctx}: to_s"
                );
            }
        }
        ("raised", Err(LintError::Raised { class, message })) => {
            assert_eq!(class, want["class"].as_str().unwrap(), "{ctx}: class");
            if !syntax {
                assert_eq!(
                    message,
                    &sub(want["message"].as_str().unwrap()),
                    "{ctx}: message"
                );
            }
        }
        (kind, got) => panic!("{ctx}: oracle {kind} {want}, port {got:?}"),
    }
}

#[test]
fn oracle_cases_lint_lint_string_lint_file_and_cli_exit() {
    let fx = fixture();
    assert_eq!(fx["oracle"], "ab6df353c6dc2d7faf7817a86aafcafa82579896");
    let outcomes = fx["outcomes"].as_array().unwrap();
    let cases = fx["cases"].as_array().unwrap();
    let dir = tmp_dir("cases");
    let (mut compared, mut unsupported, mut cli) = (0usize, 0usize, 0usize);

    for (i, case) in cases.iter().enumerate() {
        let id = case["id"].as_str().unwrap();
        let yaml = case["yaml"].as_str().unwrap();
        let rules = rule_filter(&case["rules"]);
        let rules = rules.as_ref();
        let syntax = SYNTAX_CASES.contains(&id);
        let path = dir.join(format!("case{i}.yaml"));
        std::fs::write(&path, yaml).unwrap();
        let path_s = path.display().to_string();

        let lint = safe_load_definition(yaml, true).and_then(|d| DefinitionLinter::lint(&d, rules));
        let lint_string = DefinitionLinter::lint_string(yaml, rules);
        let lint_file = DefinitionLinter::lint_file(&path, rules);

        if UNSUPPORTED_CASES.contains(&id) {
            for got in [&lint, &lint_string, &lint_file] {
                assert!(
                    matches!(got, Err(LintError::Unsupported { .. })),
                    "{id}: expected unsupported, got {got:?}"
                );
            }
            unsupported += 1;
            continue;
        }

        let o = |api: &str| &outcomes[case[api].as_u64().unwrap() as usize];
        check(&format!("{id} lint"), o("lint"), &lint, None, syntax);
        check(
            &format!("{id} lint_string"),
            o("lint_string"),
            &lint_string,
            None,
            syntax,
        );
        check(
            &format!("{id} lint_file"),
            o("lint_file"),
            &lint_file,
            Some(&path_s),
            syntax,
        );
        compared += 3;

        // `ukiryu lint file PATH --format json`: prints `to_h.to_json` and
        // exits 1 when the result has errors; a raised error escapes.
        if let Some(idx) = case.get("cli_file").and_then(Value::as_u64) {
            let cli_out = &outcomes[idx as usize];
            match &cli_out["exit"] {
                Value::Number(n) => {
                    let res = lint_file.as_ref().expect("cli exit implies a result");
                    let exit = n.as_u64().unwrap();
                    assert_eq!(u64::from(res.has_errors()), exit, "{id}: cli exit");
                    if !syntax {
                        assert_eq!(
                            format!("{}\n", res.to_json()),
                            cli_out["stdout"]
                                .as_str()
                                .unwrap()
                                .replace("{path}", &path_s),
                            "{id}: cli json"
                        );
                    }
                }
                raised => {
                    let Err(LintError::Raised { class, .. }) = &lint_file else {
                        panic!("{id}: cli raised {raised}, port {lint_file:?}");
                    };
                    assert_eq!(class, raised["raised"].as_str().unwrap(), "{id}: cli raise");
                }
            }
            cli += 1;
        }
    }
    let _ = std::fs::remove_dir_all(&dir);
    eprintln!(
        "cases={} compared_outcomes={compared} unsupported_cases={unsupported} cli_exits={cli}",
        cases.len()
    );
    assert_eq!(compared + unsupported * 3, cases.len() * 3);
    assert!(compared >= 450, "compared {compared}");
}

#[test]
fn lint_file_filesystem_outcomes() {
    let fx = fixture();
    let outcomes = fx["outcomes"].as_array().unwrap();
    let fs = &fx["fs"];
    let o = |name: &str| &outcomes[fs[name]["lint_file"].as_u64().unwrap() as usize];

    // Relative path, as the Ruby spec uses it.
    let got = DefinitionLinter::lint_file("nonexistent.yaml", None);
    check(
        "not_found_relative",
        o("not_found_relative"),
        &got,
        None,
        false,
    );
    let want_cli = fx["fs_cli"]["not_found_relative"]["stdout"]
        .as_str()
        .unwrap()
        .replace("{path}", "nonexistent.yaml");
    assert_eq!(fx["fs_cli"]["not_found_relative"]["exit"], 1);
    assert_eq!(format!("{}\n", got.unwrap().to_json()), want_cli);

    let dir = tmp_dir("fs");
    let missing = dir.join("missing").join("x.yaml");
    let got = DefinitionLinter::lint_file(&missing, None);
    check(
        "not_found_absolute",
        o("not_found_absolute"),
        &got,
        Some(&missing.display().to_string()),
        false,
    );

    #[cfg(unix)]
    {
        let got = DefinitionLinter::lint_file(&dir, None);
        check(
            "directory",
            o("directory"),
            &got,
            Some(&dir.display().to_string()),
            false,
        );
        let file = dir.join("case0.yaml");
        std::fs::write(&file, "name: x\n").unwrap();
        let notdir = file.join("x.yaml");
        let got = DefinitionLinter::lint_file(&notdir, None);
        check(
            "not_a_directory",
            o("not_a_directory"),
            &got,
            Some(&notdir.display().to_string()),
            false,
        );
    }
    let _ = std::fs::remove_dir_all(&dir);
}

fn severity(s: &str) -> Severity {
    match s {
        "error" => Severity::Error,
        "warning" => Severity::Warning,
        "info" => Severity::Info,
        "style" => Severity::Style,
        other => Severity::Other(other.to_owned()),
    }
}

fn opt(v: &Value) -> Option<String> {
    v.as_str().map(str::to_owned)
}

#[test]
fn lint_result_on_built_issues() {
    let fx = fixture();
    let built = fx["built"].as_object().unwrap();
    assert_eq!(built.len(), 4);
    for (name, b) in built {
        let issues: Vec<LintIssue> = b["issues"]
            .as_array()
            .unwrap()
            .iter()
            .map(|i| {
                LintIssue::new(
                    severity(i["severity"].as_str().unwrap()),
                    i["message"].as_str().unwrap(),
                    opt(&i["location"]),
                    opt(&i["suggestion"]),
                    opt(&i["rule_id"]),
                )
            })
            .collect();
        let res = LintResult::new(issues);
        check(name, &b["result"], &Ok(res.clone()), None, false);
        for (sev, n) in b["count_by_severity"].as_object().unwrap() {
            assert_eq!(
                res.count_by_severity(&severity(sev)) as u64,
                n.as_u64().unwrap(),
                "{name}: count_by_severity({sev})"
            );
        }
        assert_eq!(res.errors().len(), res.count_by_severity(&Severity::Error));
        assert_eq!(
            res.warnings().len(),
            res.count_by_severity(&Severity::Warning)
        );
        assert_eq!(res.infos().len(), res.count_by_severity(&Severity::Info));
        assert_eq!(res.styles().len(), res.count_by_severity(&Severity::Style));
    }
}

#[test]
fn rules_constants_match_oracle() {
    let fx = fixture();
    let groups: [(&str, &[(&str, Rule)]); 4] = [
        ("naming", &rules::NAMING_RULES),
        ("completeness", &rules::COMPLETENESS_RULES),
        ("security", &rules::SECURITY_RULES),
        ("deprecated", &rules::DEPRECATED_RULES),
    ];
    for (group, list) in groups {
        let want = fx["rules"][group].as_object().unwrap();
        let keys: Vec<&str> = want.keys().map(String::as_str).collect();
        let mut ours: Vec<&str> = list.iter().map(|(k, _)| *k).collect();
        ours.sort_unstable();
        let mut keys_sorted = keys.clone();
        keys_sorted.sort_unstable();
        assert_eq!(ours, keys_sorted, "{group} keys");
        for (key, rule) in list {
            let w = &want[*key];
            assert_eq!(w["rule_id"], rule.rule_id, "{group}.{key}");
            assert_eq!(w["message"], rule.message, "{group}.{key}");
            assert_eq!(w["suggestion"], rule.suggestion, "{group}.{key}");
            assert_eq!(opt(&w["pattern"]).as_deref(), rule.pattern, "{group}.{key}");
            assert_eq!(
                opt(&w["threshold"]).as_deref(),
                rule.threshold,
                "{group}.{key}"
            );
        }
    }
}

/// `ukiryu lint all` calls `LintResult#error_count`, which does not exist,
/// so the original command raises once it has linted any file. The port
/// does not add the method; this records the captured behaviour.
#[test]
fn cli_lint_all_finding_is_recorded() {
    let fx = fixture();
    assert_eq!(fx["cli_all"]["kind"], "raised");
    assert_eq!(fx["cli_all"]["class"], "NoMethodError");
    assert_eq!(
        fx["cli_all"]["message"],
        "undefined method 'error_count' for an instance of Ukiryu::Definition::DefinitionLinter::LintResult"
    );
}

/// The spec's own expectations, stated directly.
#[test]
fn spec_examples() {
    let def = safe_load_definition("name: TestTool\n", true).unwrap();
    let res = DefinitionLinter::lint(&def, None).unwrap();
    assert!(res.has_issues());
    assert!(res.warnings()[0].message.contains("lowercase"));

    let off = RuleFilter {
        disabled: Some(vec!["naming_tool_name_format".into()]),
        ..Default::default()
    };
    let res = DefinitionLinter::lint(&def, Some(&off)).unwrap();
    assert!(res
        .warnings()
        .iter()
        .all(|w| w.rule_id.as_deref() != Some("naming_tool_name_format")));

    let res = DefinitionLinter::lint_string("not-a-hash", None).unwrap();
    assert!(res.has_errors());
    assert!(res.errors()[0].message.contains("hash/object"));

    let res = DefinitionLinter::lint_string("name: : test", None).unwrap();
    assert!(res.errors()[0].message.starts_with("Invalid YAML"));

    assert_eq!(LintResult::default().to_string(), "No issues found");
}
